export const TRACK1_YAML = "id: track-1\ntitle: First Steps\nlevel: Beginner\ndescription: Never typed a command in your life? Start here. You'll learn to see, move, and touch files — the foundation of everything else.\nlessons:\n  - id: t1-l1\n    title: Say hello to the shell\n    tool: shell\n    world: fs\n    intro: |\n      Welcome to your terminal. Everything here happens by typing commands and pressing Enter.\n\n      The line with the blinking cursor is called the PROMPT. It looks like:\n\n        learner@terminaltype:~$\n\n      That \"~\" means you're in your home folder. Ready? First command: pwd.\n      It stands for \"print working directory\" — it shows where you are.\n    seed:\n      - op: touch\n        name: welcome.txt\n    exercises:\n      - id: ex1\n        prompt: \"Type pwd and press Enter to see where you are.\"\n        accept:\n          - cmd: pwd\n            label: pwd\n        tips:\n          \"cmd:pdw\": Almost! You swapped two letters — it's pwd (print working directory).\n          \"cmd:cd\": cd changes your location. pwd *prints* it. Try pwd.\n        hint: pwd\n      - id: ex2\n        prompt: \"Now type ls to list what's in this folder.\"\n        accept:\n          - cmd: ls\n            label: ls\n        tips:\n          \"cmd:dir\": dir is the Windows command — in this POSIX-flavored shell, use ls.\n          \"cmd:sl\": So close — the train has left the station. It's ls (lowercase L, lowercase s).\n        hint: ls\n      - id: ex3\n        prompt: \"There's a file called welcome.txt. Read it with cat welcome.txt.\"\n        accept:\n          - cmd: cat\n            args: [\"welcome.txt\"]\n            label: cat welcome.txt\n        tips:\n          \"cmd:cat noarg:welcome.txt\": cat needs to know *which* file — add the filename after it.\n          \"cmd:touch\": touch creates empty files. cat *reads* them. Try cat welcome.txt.\n        hint: cat welcome.txt\n    badge: first-command\n\n  - id: t1-l2\n    title: Listing files like a pro\n    tool: ls\n    world: fs\n    intro: |\n      ls lists directory contents. It has FLAGS — options that start with a dash:\n\n        ls          plain listing\n        ls docs     list the \"docs\" folder without entering it\n        ls -a       also show HIDDEN files (they start with a dot)\n\n      In this folder there's a projects directory and a sneaky hidden file.\n    seed:\n      - op: mkdir\n        name: projects\n      - op: touch\n        name: todo.txt\n      - op: touch\n        name: .treasure\n        content: \"X marks the spot. You found hidden files!\"\n    exercises:\n      - id: ex1\n        prompt: \"List the contents of the projects folder without leaving home: ls projects\"\n        accept:\n          - cmd: ls\n            args: [\"projects\"]\n            label: ls projects\n          - cmd: ls\n            flags: [[\"-l\"]]\n            args: [\"projects\"]\n            label: ls -l projects\n        tips:\n          \"cmd:cd arg:projects\": That works too, but you can peek into a folder without moving — try ls projects.\n        hint: ls projects\n      - id: ex2\n        prompt: \"Hidden files start with a dot and are invisible to plain ls. Reveal them with ls -a\"\n        accept:\n          - cmd: ls\n            flags: [[\"-a\", \"--all\"]]\n            label: ls -a\n        tips:\n          \"cmd:ls flag:-l\": -l shows the long format with permissions — handy, but the flag you want here is -a (all).\n          \"cmd:ls flag:-la\": -la works — -l is the long format and -a includes hidden files. But plain ls -a is all this task needs. Try just ls -a.\n        hint: ls -a\n      - id: ex3\n        prompt: \"You spotted .treasure. Read it with cat .treasure\"\n        accept:\n          - cmd: cat\n            args: [\".treasure\"]\n            label: cat .treasure\n        hint: cat .treasure\n    badge: hidden-seeker\n\n  - id: t1-l3\n    title: Moving around with cd\n    tool: cd\n    world: fs\n    intro: |\n      cd changes your current directory (\"change directory\").\n\n        cd projects    go INTO the projects folder (relative path)\n        cd ..          go UP one level\n        cd ~           jump back to your home folder\n\n      Your home folder has a projects directory inside it.\n    seed:\n      - op: mkdir\n        name: projects\n      - op: mkdir\n        name: projects/web\n      - op: touch\n        name: projects/notes.md\n        content: notes from the projects folder\n    exercises:\n      - id: ex1\n        prompt: \"Go into the projects folder: cd projects\"\n        accept:\n          - cmd: cd\n            args: [\"projects\"]\n            label: cd projects\n        tips:\n          \"cmd:cd noarg:projects\": cd needs the folder name — try cd projects.\n          \"cmd:ls\": ls lists files, it doesn't move you. Use cd projects.\n        hint: cd projects\n      - id: ex2\n        prompt: \"Check where you are now with pwd. Notice the path changed!\"\n        accept:\n          - cmd: pwd\n            label: pwd\n        hint: pwd\n      - id: ex3\n        prompt: \"Go back up one level with cd ..\"\n        accept:\n          - cmd: cd\n            args: [\"..\"]\n            label: cd ..\n        tips:\n          \"cmd:cd arg:~\": \"cd ~ jumps all the way home. Great shortcut, but this task wants the one-level-up move: cd ..\"\n        hint: cd ..\n      - id: ex4\n        prompt: \"Now use an ABSOLUTE path to reach projects/web in one hop: cd /projects/web\"\n        accept:\n          - cmd: cd\n            args: [\"/projects/web\"]\n            label: cd /projects/web\n        tips:\n          \"cmd:cd arg:projects/web\": \"That's the relative path (two hops). Absolute paths start with a slash: cd /projects/web\"\n        hint: cd /projects/web\n      - id: ex5\n        prompt: \"Home time — jump back with cd ~\"\n        accept:\n          - cmd: cd\n            args: [\"~\"]\n            label: cd ~\n          - cmd: cd\n            label: cd\n        hint: cd ~\n    badge: navigator\n\n  - id: t1-l4\n    title: Making things — mkdir & touch\n    tool: mkdir\n    world: fs\n    intro: |\n      You can create things from the terminal too:\n\n        mkdir <name>    makes a new directory (folder)\n        touch <name>    makes a new empty file\n\n      If mkdir says \"File exists\", that folder is already there — the terminal never destroys things silently.\n    exercises:\n      - id: ex1\n        prompt: \"Create a folder called websites: mkdir websites\"\n        accept:\n          - cmd: mkdir\n            args: [\"websites\"]\n            label: mkdir websites\n        tips:\n          \"cmd:touch arg:websites\": touch makes FILES. For a folder, use mkdir websites.\n        hint: mkdir websites\n      - id: ex2\n        prompt: \"Create an empty file called ideas.txt: touch ideas.txt\"\n        accept:\n          - cmd: touch\n            args: [\"ideas.txt\"]\n            label: touch ideas.txt\n        tips:\n          \"cmd:mkdir arg:ideas.txt\": mkdir makes FOLDERS. For a file, use touch ideas.txt.\n        hint: touch ideas.txt\n      - id: ex3\n        prompt: \"Verify both exist with ls\"\n        accept:\n          - cmd: ls\n            label: ls\n        hint: ls\n      - id: ex4\n        prompt: \"Cleanup time — delete ideas.txt with rm ideas.txt\"\n        accept:\n          - cmd: rm\n            args: [\"ideas.txt\"]\n            label: rm ideas.txt\n        tips:\n          \"cmd:rm arg:websites\": websites is a folder — rm needs -r for those. But this task only asks you to delete the FILE ideas.txt.\n        hint: rm ideas.txt\n    badge: maker\n\n  - id: t1-l5\n    title: Reading files with cat\n    tool: cat\n    world: fs\n    intro: |\n      cat prints a file's contents to the terminal.\n\n        cat <file>              read one file\n        cat <file1> <file2>     read several in order\n\n      Careful: cat on a folder says \"Is a directory\" — it only reads files.\n    seed:\n      - op: write\n        name: chapter1.txt\n        content: \"It was a dark and stormy night in the terminal...\"\n      - op: write\n        name: chapter2.txt\n        content: \"Suddenly, the prompt blinked twice. The end.\"\n    exercises:\n      - id: ex1\n        prompt: \"Read chapter1.txt\"\n        accept:\n          - cmd: cat\n            args: [\"chapter1.txt\"]\n            label: cat chapter1.txt\n        hint: cat chapter1.txt\n      - id: ex2\n        prompt: \"Read chapter2.txt\"\n        accept:\n          - cmd: cat\n            args: [\"chapter2.txt\"]\n            label: cat chapter2.txt\n        hint: cat chapter2.txt\n      - id: ex3\n        prompt: \"Bonus — read BOTH with one command: cat chapter1.txt chapter2.txt\"\n        accept:\n          - cmd: cat\n            args: [\"chapter1.txt\", \"chapter2.txt\"]\n            label: cat chapter1.txt chapter2.txt\n        hint: cat chapter1.txt chapter2.txt\n    badge: reader\n\n  - id: t1-l6\n    title: Paths — where am I, where is it\n    tool: paths\n    world: fs\n    intro: |\n      Two ways to name locations:\n\n        RELATIVE:  from where you stand now     (docs/notes.txt)\n        ABSOLUTE:  from the root, starts with / (/home/learner/docs/notes.txt)\n\n      pwd prints where you are. combine with cd .. to climb.\n    seed:\n      - op: mkdir\n        name: docs\n      - op: write\n        path: docs\n        name: notes.txt\n        content: \"Relative paths are measured from the current directory.\"\n      - op: mkdir\n        name: docs/archive\n    exercises:\n      - id: ex1\n        prompt: \"Enter the docs folder: cd docs\"\n        accept:\n          - cmd: cd\n            args: [\"docs\"]\n            label: cd docs\n        tips:\n          \"cmd:ls\": ls lists files but doesn't move you — cd docs is the mover.\n        hint: cd docs\n      - id: ex2\n        prompt: \"Now check where you are with pwd — see the /docs at the end?\"\n        accept:\n          - cmd: pwd\n            label: pwd\n        hint: pwd\n      - id: ex3\n        prompt: \"From inside docs, read notes.txt using a RELATIVE path: cat notes.txt\"\n        accept:\n          - cmd: cat\n            args: [\"notes.txt\"]\n            label: cat notes.txt\n        hint: cat notes.txt\n      - id: ex4\n        prompt: \"Now climb out with cd .. and read the same file ABSOLUTELY: cat /docs/notes.txt\"\n        accept:\n          - cmd: cat\n            args: [\"/docs/notes.txt\"]\n            label: cat /docs/notes.txt\n        hint: cd .. then cat /docs/notes.txt\n    badge: pathfinder\n\n  - id: t1-l7\n    title: Chain of power — combining commands\n    tool: shell\n    world: fs\n    intro: |\n      Real workflows chain what you've learned. A taste of the pattern:\n\n        mkdir site\n        touch site/index.html\n\n      One command per line, each building on the last.\n    exercises:\n      - id: ex1\n        prompt: \"Make a folder called site\"\n        accept:\n          - cmd: mkdir\n            args: [\"site\"]\n            label: mkdir site\n        hint: mkdir site\n      - id: ex2\n        prompt: \"Inside site, create index.html — either cd in first, or touch site/index.html directly\"\n        accept:\n          - cmd: touch\n            args: [\"site/index.html\"]\n            label: touch site/index.html\n          - cmd: touch\n            args: [\"site\", \"index.html\"]\n            label: touch site/index.html\n        tips:\n          \"cmd:touch arg:index.html\": \"touch index.html would create it HERE. Add the folder: touch site/index.html\"\n        hint: touch site/index.html\n      - id: ex3\n        prompt: \"Confirm the file is there: ls site\"\n        accept:\n          - cmd: ls\n            args: [\"site\"]\n            label: ls site\n        hint: ls site\n    badge: builder\n\n  - id: t1-l8\n    title: BOSS — The hidden treasure\n    tool: shell\n    world: fs\n    boss: true\n    intro: |\n      FINAL CHALLENGE of Track 1. Somewhere in this filesystem hides a secret file.\n\n      Your toolkit: ls -a (reveal hidden), cd (move), cat (read).\n\n      No step-by-step this time. Trust the prompt, young one.\n    seed:\n      - op: mkdir\n        name: work\n      - op: mkdir\n        name: work/deep\n      - op: mkdir\n        name: work/deep/deeper\n      - op: write\n        path: work/deep/deeper\n        name: .secret\n        content: \"🏆 You found the hidden treasure. Track 1 complete — you officially know your way around a terminal.\"\n      - op: write\n        path: work\n        name: readme.txt\n        content: \"The secret is deeper. And hidden. And starts with a dot.\"\n      - op: touch\n        name: decoy.txt\n    exercises:\n      - id: ex1\n        prompt: \"Explore and locate the hidden file inside work/deep/deeper\"\n        accept:\n          - cmd: ls\n            flags: [[\"-a\", \"--all\"]]\n            args: [\"/work/deep/deeper\"]\n            label: ls -a /work/deep/deeper\n          - cmd: ls\n            flags: [[\"-a\", \"--all\"]]\n            args: [\"work/deep/deeper\"]\n            label: ls -a work/deep/deeper\n        tips:\n          \"cmd:find\": find is a real command but not taught yet — explore with ls -a and cd.\n          \"cmd:ls noflag:-a\": Plain ls won't show hidden files. Add -a.\n        hint: cd work, then ls -a, and keep going deeper\n      - id: ex2\n        prompt: \"Reveal the secret — cat the hidden file you found.\"\n        accept:\n          - cmd: cat\n            args: [\".secret\"]\n            label: cat .secret\n            canonical: \"cat work/deep/deeper/.secret\"\n          - cmd: cat\n            args: [\"work/deep/deeper/.secret\"]\n            label: cat work/deep/deeper/.secret\n          - cmd: cat\n            args: [\"/work/deep/deeper/.secret\"]\n            label: cat /work/deep/deeper/.secret\n        tips:\n          \"cmd:cat arg:decoy.txt\": That's a decoy! The real file starts with a dot.\n        hint: from anywhere — cat /work/deep/deeper/.secret\n    badge: track-1-champion\n"

export const TRACK2_YAML = "id: track-2\ntitle: Everyday Power\nlevel: Intermediate\ndescription: The tools you'll touch every single day — git version control, grep searching, and npm package management.\nlessons:\n  - id: t2-l1\n    title: git init — start tracking\n    tool: git\n    world: git\n    intro: |\n      git records the history of your project so you can rewind, branch, and collaborate.\n\n      Everything starts the same way:\n\n        git init\n\n      This creates a hidden .git folder — the \"time machine\".\n    exercises:\n      - id: ex1\n        prompt: \"Turn this folder into a git repository: git init\"\n        accept:\n          - cmd: git\n            args: [\"init\"]\n            label: git init\n        tips:\n          \"cmd:git arg:start\": Cute, but the command is git init (initialize).\n          \"cmd:git sub:install\": git isn't installed per-project — git init is what you want.\n        hint: git init\n      - id: ex2\n        prompt: \"Ask git what's going on: git status\"\n        accept:\n          - cmd: git\n            args: [\"status\"]\n            label: git status\n        tips:\n          \"cmd:git sub:statu\": Typo! git status.\n        hint: git status\n    badge: git-born\n\n  - id: t2-l2\n    title: git status — read the room\n    tool: git\n    world: git\n    intro: |\n      git status is your dashboard. It tells you:\n\n        Untracked files   — new files git isn't watching yet\n        Modified files    — watched files you've changed\n        Staged changes    — files ready to be committed\n\n      There's a modified file in this repo. Let's find it.\n    seed:\n      - op: gitInit\n      - op: gitModify\n        path: README.md\n      - op: touch\n        name: app.js\n    exercises:\n      - id: ex1\n        prompt: \"Run git status and find the modified file.\"\n        accept:\n          - cmd: git\n            args: [\"status\"]\n            label: git status\n        hint: git status\n      - id: ex2\n        prompt: \"See WHAT changed in README.md with git diff\"\n        accept:\n          - cmd: git\n            args: [\"diff\"]\n            label: git diff\n        hint: git diff\n    badge: status-reader\n\n  - id: t2-l3\n    title: git add — stage your work\n    tool: git\n    world: git\n    intro: |\n      Before committing, you STAGE changes — pick exactly what goes into the next save:\n\n        git add <file>    stage one file\n        git add .         stage everything\n\n      Think of staging as packing a box. The commit ships the box.\n    seed:\n      - op: gitInit\n      - op: gitModify\n        path: README.md\n      - op: touch\n        name: app.js\n    exercises:\n      - id: ex1\n        prompt: \"Stage the modified README.md: git add README.md\"\n        accept:\n          - cmd: git\n            args: [\"add\", \"README.md\"]\n            label: git add README.md\n        tips:\n          \"cmd:git sub:add noarg:README.md\": \"git add needs the filename: git add README.md\"\n          \"cmd:git sub:stage\": close — staging is done with git add.\n        hint: git add README.md\n      - id: ex2\n        prompt: \"Check status — README.md should now be under \\\"Changes to be committed\\\".\"\n        accept:\n          - cmd: git\n            args: [\"status\"]\n            label: git status\n        hint: git status\n      - id: ex3\n        prompt: \"Stage everything remaining: git add .\"\n        accept:\n          - cmd: git\n            args: [\"add\", \".\"]\n            label: git add .\n          - cmd: git\n            args: [\"add\", \"-A\"]\n            label: git add -A\n        hint: git add .\n    badge: stage-master\n\n  - id: t2-l4\n    title: git commit — save the game\n    tool: git\n    world: git\n    intro: |\n      A commit is a snapshot — a save point you can return to.\n\n        git commit -m \"message\"\n\n      The -m flag passes the message inline. Without it, git opens an editor.\n      Good messages say WHAT and WHY: \"fix login redirect bug\", not \"changes\".\n    seed:\n      - op: gitInit\n      - op: gitModify\n        path: README.md\n    exercises:\n      - id: ex1\n        prompt: \"Stage README.md first (git add README.md), then commit with git commit -m \\\"your message\\\"\"\n        accept:\n          - cmd: git\n            args: [\"commit\", \"*\"]\n            flags: [[\"-m\"]]\n            canonical: \"git add . && git commit -m msg\"\n            label: git commit -m \"...\"\n        tips:\n          \"cmd:git sub:commit noflag:-m\": git without -m tries to open an editor — always use -m with a message.\n        hint: git add README.md, then git commit -m \"message\"\n      - id: ex2\n        prompt: \"Confirm with git status — working tree should be clean.\"\n        accept:\n          - cmd: git\n            args: [\"status\"]\n            label: git status\n        hint: git status\n      - id: ex3\n        prompt: \"Time travel check — view history with git log\"\n        accept:\n          - cmd: git\n            args: [\"log\"]\n            label: git log\n        hint: git log\n    badge: committer\n\n  - id: t2-l5\n    title: git branch — parallel universes\n    tool: git\n    world: git\n    intro: |\n      Branches let you work on features without breaking the main code.\n\n        git branch <name>      create a branch\n        git branch             list branches (* = where you are)\n        git switch <name>      move to a branch (modern command)\n        git checkout -b <n>    create AND move (classic command)\n    seed:\n      - op: gitInit\n      - op: gitModify\n        path: README.md\n    exercises:\n      - id: ex1\n        prompt: \"Create a branch called feature/login: git branch feature/login\"\n        accept:\n          - cmd: git\n            args: [\"branch\", \"feature/login\"]\n            label: git branch feature/login\n        hint: git branch feature/login\n      - id: ex2\n        prompt: \"List branches — you should still be on main.\"\n        accept:\n          - cmd: git\n            args: [\"branch\"]\n            label: git branch\n        hint: git branch\n      - id: ex3\n        prompt: \"Switch to it: git switch feature/login (or git checkout feature/login)\"\n        accept:\n          - cmd: git\n            args: [\"switch\", \"feature/login\"]\n            label: git switch feature/login\n          - cmd: git\n            args: [\"checkout\", \"feature/login\"]\n            label: git checkout feature/login\n        hint: git switch feature/login\n    badge: brancher\n\n  - id: t2-l6\n    title: git merge — bring it home\n    tool: git\n    world: git\n    intro: |\n      When feature work is done, you MERGE it back:\n\n        git switch main       go to the destination branch\n        git merge <branch>    pull that branch's work in\n\n      This repo has a finished feature branch waiting.\n    seed:\n      - op: gitInit\n      - op: gitModify\n        path: README.md\n    exercises:\n      - id: ex1\n        prompt: \"Create and switch to a feature branch in one step: git checkout -b feature/buttons\"\n        accept:\n          - cmd: git\n            args: [\"checkout\", \"-b\", \"feature/buttons\"]\n            label: git checkout -b feature/buttons\n          - cmd: git\n            args: [\"switch\", \"-c\", \"feature/buttons\"]\n            label: git switch -c feature/buttons\n        hint: git checkout -b feature/buttons\n      - id: ex2\n        prompt: \"Stage and commit a change so the branch has work on it — git add . then commit with -m\"\n        accept:\n          - cmd: git\n            args: [\"add\", \".\"]\n            label: git add .\n          - cmd: git\n            args: [\"commit\", \"*\"]\n            flags: [[\"-m\"]]\n            canonical: \"git add . && git commit -m msg\"\n            label: git commit -m \"...\"\n        hint: git add . then git commit -m \"add buttons\"\n      - id: ex3\n        prompt: \"If you committed — go back to main: git switch main\"\n        accept:\n          - cmd: git\n            args: [\"switch\", \"main\"]\n            label: git switch main\n          - cmd: git\n            args: [\"checkout\", \"main\"]\n            label: git checkout main\n        hint: git switch main\n      - id: ex4\n        prompt: \"Now merge the feature in: git merge feature/buttons\"\n        accept:\n          - cmd: git\n            args: [\"merge\", \"feature/buttons\"]\n            label: git merge feature/buttons\n        hint: git merge feature/buttons\n    badge: merger\n\n  - id: t2-l7\n    title: git remote — push to the world\n    tool: git\n    world: git\n    intro: |\n      Remotes are copies of your repo on other machines (like GitHub).\n\n        git remote add origin <url>   connect a remote\n        git push -u origin main       upload your commits\n    seed:\n      - op: gitInit\n      - op: gitModify\n        path: README.md\n    exercises:\n      - id: ex1\n        prompt: \"Commit your work first — git add . then git commit -m \\\"...\\\"\"\n        accept:\n          - cmd: git\n            args: [\"commit\", \"*\"]\n            flags: [[\"-m\"]]\n            canonical: \"git add . && git commit -m msg\"\n            label: git commit -m \"...\"\n        hint: git add . then git commit -m \"first commit\"\n      - id: ex2\n        prompt: \"Connect a remote called origin: git remote add origin git@github.com:you/project.git\"\n        accept:\n          - cmd: git\n            args: [\"remote\", \"add\", \"origin\", \"*\"]\n            label: git remote add origin <url>\n        tips:\n          \"cmd:git sub:remote sub:add\": \"you need all three parts: git remote add <name> <url>\"\n        hint: git remote add origin git@github.com:you/project.git\n      - id: ex3\n        prompt: \"Push your work: git push -u origin main\"\n        accept:\n          - cmd: git\n            args: [\"push\"]\n            canonical: \"git push\"\n            label: git push -u origin main\n          - cmd: git\n            args: [\"push\", \"-u\", \"origin\", \"main\"]\n            label: git push -u origin main\n        hint: git push -u origin main\n    badge: publisher\n\n  - id: t2-l8\n    title: BOSS — Ship a feature\n    tool: git\n    world: git\n    boss: true\n    intro: |\n      BOSS FIGHT: the full git workflow, no training wheels.\n\n      1. branch feature/copy\n      2. stage + commit work on it\n      3. switch back to main\n      4. merge the feature\n      5. push to origin\n\n      The repo already has a remote configured and modified files.\n    seed:\n      - op: gitInit\n      - op: gitModify\n        path: README.md\n      - op: gitRemote\n        name: origin\n    exercises:\n      - id: ex1\n        prompt: \"Step 1 — create and switch to feature/copy\"\n        accept:\n          - cmd: git\n            args: [\"checkout\", \"-b\", \"feature/copy\"]\n            label: git checkout -b feature/copy\n          - cmd: git\n            args: [\"switch\", \"-c\", \"feature/copy\"]\n            label: git switch -c feature/copy\n        hint: git checkout -b feature/copy\n      - id: ex2\n        prompt: \"Step 2 — stage everything and commit with a message\"\n        accept:\n          - cmd: git\n            args: [\"commit\", \"*\"]\n            flags: [[\"-m\"]]\n            canonical: \"git add . && git commit -m msg\"\n            label: git commit -m \"...\"\n        tips:\n          \"cmd:git sub:commit\": stage first with git add . — then commit with -m.\n        hint: git add . && git commit -m \"update copy\"\n      - id: ex3\n        prompt: \"Step 3 — back to main\"\n        accept:\n          - cmd: git\n            args: [\"switch\", \"main\"]\n            label: git switch main\n          - cmd: git\n            args: [\"checkout\", \"main\"]\n            label: git checkout main\n        hint: git switch main\n      - id: ex4\n        prompt: \"Step 4 — merge feature/copy into main\"\n        accept:\n          - cmd: git\n            args: [\"merge\", \"feature/copy\"]\n            label: git merge feature/copy\n        hint: git merge feature/copy\n      - id: ex5\n        prompt: \"Step 5 — push it\"\n        accept:\n          - cmd: git\n            args: [\"push\"]\n            canonical: \"git push\"\n            label: git push\n        hint: git push\n    badge: feature-shipper\n\n  - id: t2-l9\n    title: grep — find anything\n    tool: grep\n    world: fs\n    intro: |\n      grep searches text inside files.\n\n        grep \"error\" log.txt     find lines containing \"error\"\n        grep -i                  case-insensitive\n        grep -n                  show line numbers\n\n      Pattern first, file second. The pattern is case-sensitive by default!\n    seed:\n      - op: write\n        name: server.log\n        content: |\n          INFO server started\n          ERROR failed to connect to database\n          INFO retrying...\n          error resolved after reboot\n          INFO all systems go\n    exercises:\n      - id: ex1\n        prompt: \"Search server.log for ERROR — capital letters matter: grep ERROR server.log\"\n        accept:\n          - cmd: grep\n            args: [\"ERROR\", \"server.log\"]\n            label: grep ERROR server.log\n        tips:\n          \"cmd:grep arg:server.log arg:ERROR\": \"order matters — grep PATTERN FILE: grep ERROR server.log\"\n          \"cmd:grep noarg:server.log\": \"give grep a pattern and a file: grep ERROR server.log\"\n        hint: grep ERROR server.log\n      - id: ex2\n        prompt: \"Now catch lowercase \\\"error\\\" too — case-insensitive: grep -i error server.log\"\n        accept:\n          - cmd: grep\n            flags: [[\"-i\"]]\n            args: [\"error\", \"server.log\"]\n            label: grep -i error server.log\n        hint: grep -i error server.log\n      - id: ex3\n        prompt: \"Show line numbers with -n: grep -n INFO server.log\"\n        accept:\n          - cmd: grep\n            flags: [[\"-n\"]]\n            args: [\"INFO\", \"server.log\"]\n            label: grep -n INFO server.log\n        hint: grep -n INFO server.log\n    badge: searcher\n\n  - id: t2-l10\n    title: grep -r — search everything\n    tool: grep\n    world: fs\n    intro: |\n      Searching file by file is for beginners. grep -r searches a whole folder RECURSIVELY:\n\n        grep -r \"TODO\" .\n\n      The dot means \"this folder and everything inside it\".\n    seed:\n      - op: mkdir\n        name: src\n      - op: write\n        path: src\n        name: app.js\n        content: \"const start = () => {\\n  // TODO: add error handling\\n  return true\\n}\"\n      - op: write\n        path: src\n        name: utils.js\n        content: \"export const ready = true\\n// TODO: remove after launch\"\n    exercises:\n      - id: ex1\n        prompt: \"Find every TODO in the whole src folder: grep -r TODO src\"\n        accept:\n          - cmd: grep\n            flags: [[\"-r\", \"-R\"]]\n            args: [\"TODO\", \"src\"]\n            label: grep -r TODO src\n        tips:\n          \"cmd:grep arg:TODO noflag:-r\": without -r, grep expects a single file. Add -r for recursive folder search.\n        hint: grep -r TODO src\n    badge: deep-searcher\n\n  - id: t2-l11\n    title: npm init — start a project\n    tool: npm\n    world: fs\n    intro: |\n      npm is the package manager for JavaScript. A project starts with:\n\n        npm init -y\n\n      The -y flag answers \"yes\" to every question and generates package.json —\n      the file that records your project's dependencies and scripts.\n    exercises:\n      - id: ex1\n        prompt: \"Initialize a project: npm init -y\"\n        accept:\n          - cmd: npm\n            args: [\"init\"]\n            label: npm init -y\n        tips:\n          \"cmd:npm sub:install\": packages later — first create package.json with npm init -y.\n        hint: npm init -y\n      - id: ex2\n        prompt: \"package.json appeared! Inspect it: cat package.json\"\n        accept:\n          - cmd: cat\n            args: [\"package.json\"]\n            label: cat package.json\n        hint: cat package.json\n    badge: project-spawner\n\n  - id: t2-l12\n    title: npm install — harness the ecosystem\n    tool: npm\n    world: fs\n    intro: |\n      Someone already solved your problem. Their code is a package:\n\n        npm install <package>       add a dependency\n        npm install                 install everything in package.json\n\n      Installing creates node_modules (the packages) and updates package.json.\n    seed:\n      - op: write\n        name: package.json\n        content: |\n          {\n            \"name\": \"sandbox\",\n            \"version\": \"1.0.0\",\n            \"scripts\": {\n              \"test\": \"echo ok\"\n            }\n          }\n    exercises:\n      - id: ex1\n        prompt: \"Install the \\\"dayjs\\\" package: npm install dayjs\"\n        accept:\n          - cmd: npm\n            args: [\"install\", \"dayjs\"]\n            label: npm install dayjs\n          - cmd: npm\n            args: [\"i\", \"dayjs\"]\n            label: npm i dayjs\n        tips:\n          \"cmd:npm sub:add\": npm add works too! But the classic spelling is npm install dayjs.\n        hint: npm install dayjs\n      - id: ex2\n        prompt: \"Check package.json — dayjs should be in dependencies now.\"\n        accept:\n          - cmd: cat\n            args: [\"package.json\"]\n            label: cat package.json\n        hint: cat package.json\n    badge: dependency-wrangler\n\n  - id: t2-l13\n    title: npm run — scripts on demand\n    tool: npm\n    world: fs\n    intro: |\n      package.json can define SCRIPTS — shortcuts for tasks:\n\n        \"scripts\": { \"dev\": \"next dev\" }\n\n      Run them with npm run <name>. Two special ones skip the word \"run\":\n\n        npm test    = npm run test\n        npm start   = npm run start\n    seed:\n      - op: write\n        name: package.json\n        content: |\n          {\n          \"name\": \"sandbox\",\n          \"scripts\": {\n            \"dev\": \"echo dev server running on :3000\",\n            \"test\": \"echo all 12 tests passed\"\n          }\n          }\n    exercises:\n      - id: ex1\n        prompt: \"Run the dev script: npm run dev\"\n        accept:\n          - cmd: npm\n            args: [\"run\", \"dev\"]\n            label: npm run dev\n        hint: npm run dev\n      - id: ex2\n        prompt: \"Tests are special — try npm test\"\n        accept:\n          - cmd: npm\n            args: [\"test\"]\n            label: npm test\n        hint: npm test\n    badge: script-runner\n\n  - id: t2-l14\n    title: BOSS — The bug hunt\n    tool: grep\n    world: fs\n    boss: true\n    intro: |\n      BOSS FIGHT: A production incident! Users report login failures.\n\n      Somewhere in src/ there's a bug marker. Find it, read the context,\n      and report the file and line. You have grep, cat, and your wits.\n    seed:\n      - op: mkdir\n        name: src\n      - op: write\n        path: src\n        name: auth.js\n        content: \"function login(user) {\\n  // FIXME: token never refreshed — breaks sessions\\n  return token\\n}\"\n      - op: write\n        path: src\n        name: api.js\n        content: \"export const get = (url) => fetch(url)\\n// TODO: add retries\"\n      - op: write\n        path: src\n        name: ui.js\n        content: \"const button = 'onclick handler missing'\"\n    exercises:\n      - id: ex1\n        prompt: \"Find the FIXME comment anywhere in src\"\n        accept:\n          - cmd: grep\n            flags: [[\"-r\", \"-R\"]]\n            args: [\"FIXME\", \"src\"]\n            label: grep -r FIXME src\n        hint: grep -r FIXME src\n      - id: ex2\n        prompt: \"Get the line number too — add -n to your search\"\n        accept:\n          - cmd: grep\n            flags: [[\"-r\", \"-R\"], [\"-n\", \"--line-number\"]]\n            args: [\"FIXME\", \"src\"]\n            label: grep -rn FIXME src\n        hint: grep -rn FIXME src\n      - id: ex3\n        prompt: \"Read the full file with the bug: cat src/auth.js\"\n        accept:\n          - cmd: cat\n            args: [\"src/auth.js\"]\n            label: cat src/auth.js\n        hint: cat src/auth.js\n    badge: bug-hunter\n"

export const TRACK3_YAML = "id: track-3\ntitle: Ops & Media\nlevel: Advanced\ndescription: Containers, clusters, and media processing — the heavy artillery of the command line.\nlessons:\n  - id: t3-l1\n    title: docker run — boxes for your code\n    tool: docker\n    world: docker\n    intro: |\n      A container packages code + dependencies so it runs identically everywhere.\n\n        docker run <image>       start a container from an image\n        docker ps                list RUNNING containers\n        docker ps -a             include stopped ones\n\n      An image is the recipe; a container is the dish.\n    seed:\n      - op: dockerImage\n        image: nginx\n        tag: latest\n        size: \"77MB\"\n      - op: dockerContainer\n        image: nginx\n        cname: web-server\n        ports: \"80/tcp\"\n    exercises:\n      - id: ex1\n        prompt: \"See what's running: docker ps\"\n        accept:\n          - cmd: docker\n            args: [\"ps\"]\n            label: docker ps\n        tips:\n          \"cmd:docker sub:ps flag:-a\": -a shows stopped containers too — but this task just wants docker ps.\n        hint: docker ps\n      - id: ex2\n        prompt: \"Start another container from the nginx image: docker run nginx\"\n        accept:\n          - cmd: docker\n            args: [\"run\", \"nginx\"]\n            label: docker run nginx\n        hint: docker run nginx\n      - id: ex3\n        prompt: \"Two containers should be running now — check with docker ps\"\n        accept:\n          - cmd: docker\n            args: [\"ps\"]\n            label: docker ps\n        hint: docker ps\n    badge: container-starter\n\n  - id: t3-l2\n    title: docker build — craft your own image\n    tool: docker\n    world: docker\n    intro: |\n      Your own apps become images with a Dockerfile — a recipe with steps:\n\n        FROM node:20-alpine     base image\n        COPY . .                copy your code in\n        RUN npm install         install dependencies\n        CMD [\"npm\", \"start\"]    command to run\n\n      Build it: docker build -t <name> .\n      -t names the image, the dot means \"build from here\".\n    exercises:\n      - id: ex1\n        prompt: \"Look at the Dockerfile in this folder: cat Dockerfile\"\n        accept:\n          - cmd: cat\n            args: [\"Dockerfile\"]\n            label: cat Dockerfile\n        hint: cat Dockerfile\n      - id: ex2\n        prompt: \"Build it into an image called my-app: docker build -t my-app .\"\n        accept:\n          - cmd: docker\n            args: [\"build\", \"*\"]\n            canonical: \"docker build -t app .\"\n            flags: [[\"-t\"]]\n            label: docker build -t my-app .\n        tips:\n          \"cmd:docker sub:build noarg:.\": \"docker build needs a context path — end your command with a dot: docker build -t my-app .\"\n          \"cmd:docker sub:build noflag:-t\": \"give your image a name with -t: docker build -t my-app .\"\n        hint: docker build -t my-app .\n      - id: ex3\n        prompt: \"List images to see your creation: docker images\"\n        accept:\n          - cmd: docker\n            args: [\"images\"]\n            label: docker images\n        hint: docker images\n    badge: image-smith\n\n  - id: t3-l3\n    title: docker logs — what's it saying\n    tool: docker\n    world: docker\n    intro: |\n      Containers run in the background — their output goes to logs:\n\n        docker logs <container>     read its output\n        docker ps                   remind yourself of names\n\n      The web-server container is chatty. Let's listen.\n    seed:\n      - op: dockerContainer\n        image: nginx\n        cname: web-server\n        ports: \"80/tcp\"\n    exercises:\n      - id: ex1\n        prompt: \"Find the container name with docker ps\"\n        accept:\n          - cmd: docker\n            args: [\"ps\"]\n            label: docker ps\n        hint: docker ps\n      - id: ex2\n        prompt: \"Read its logs: docker logs web-server\"\n        accept:\n          - cmd: docker\n            args: [\"logs\", \"web-server\"]\n            label: docker logs web-server\n        tips:\n          \"cmd:docker sub:logs noarg:web-server\": \"docker logs needs the container name: docker logs web-server\"\n        hint: docker logs web-server\n    badge: log-whisperer\n\n  - id: t3-l4\n    title: BOSS — Containerize the app\n    tool: docker\n    world: docker\n    boss: true\n    intro: |\n      BOSS: full container lifecycle. The Dockerfile is ready.\n\n      1. read the Dockerfile\n      2. build an image tagged shop-api\n      3. verify it in docker images\n      4. run a container from it\n      5. check the logs\n    exercises:\n      - id: ex1\n        prompt: \"Step 1 — inspect the recipe\"\n        accept:\n          - cmd: cat\n            args: [\"Dockerfile\"]\n            label: cat Dockerfile\n        hint: cat Dockerfile\n      - id: ex2\n        prompt: \"Step 2 — build image shop-api\"\n        accept:\n          - cmd: docker\n            args: [\"build\", \"*\"]\n            canonical: \"docker build -t shop-api .\"\n            flags: [[\"-t\"]]\n            label: docker build -t shop-api .\n        hint: docker build -t shop-api .\n      - id: ex3\n        prompt: \"Step 3 — confirm the image exists\"\n        accept:\n          - cmd: docker\n            args: [\"images\"]\n            label: docker images\n        hint: docker images\n      - id: ex4\n        prompt: \"Step 4 — run a container from shop-api\"\n        accept:\n          - cmd: docker\n            args: [\"run\", \"shop-api\"]\n            label: docker run shop-api\n        hint: docker run shop-api\n      - id: ex5\n        prompt: \"Step 5 — find the container name, then read its logs\"\n        accept:\n          - cmd: docker\n            args: [\"logs\", \"sandbox-container\"]\n            label: docker logs <name>\n        tips:\n          \"cmd:docker sub:logs\": grab the exact container name from docker ps first.\n        hint: docker ps, then docker logs <name>\n    badge: container-champion\n\n  - id: t3-l5\n    title: kubectl get — see the cluster\n    tool: kubectl\n    world: k8s\n    intro: |\n      Kubernetes runs containers across many machines. kubectl talks to the cluster:\n\n        kubectl get pods       list pods (smallest units)\n        kubectl get deploy     list deployments\n        kubectl get svc        list services\n\n      A POD wraps your container. A DEPLOYMENT keeps N of them alive.\n    seed:\n      - op: k8sPod\n        name: web-app-7d9f8\n        image: web-app:latest\n      - op: k8sPod\n        name: web-app-2m4x1\n        image: web-app:latest\n      - op: k8sPod\n        name: queue-worker-8sd2\n        image: worker:2.1\n    exercises:\n      - id: ex1\n        prompt: \"List the pods: kubectl get pods\"\n        accept:\n          - cmd: kubectl\n            args: [\"get\", \"pods\"]\n            label: kubectl get pods\n          - cmd: kubectl\n            args: [\"get\", \"po\"]\n            label: kubectl get po\n        tips:\n          \"cmd:kubectl arg:get\": order — kubectl get pods. get first, then the resource.\n        hint: kubectl get pods\n      - id: ex2\n        prompt: \"Which pod is running the worker image? Check the IMAGE column, then get pods again if you need.\"\n        accept:\n          - cmd: kubectl\n            args: [\"get\", \"pods\"]\n            label: kubectl get pods\n        hint: kubectl get pods\n    badge: cluster-eyes\n\n  - id: t3-l6\n    title: kubectl apply — declare your state\n    tool: kubectl\n    world: k8s\n    intro: |\n      You don't tell Kubernetes what to do — you declare what you WANT:\n\n        kubectl apply -f deployment.yaml\n\n      The cluster reads the YAML and makes reality match. If a pod dies,\n      the deployment replaces it. That's \"reconciliation\".\n    exercises:\n      - id: ex1\n        prompt: \"Read the deployment.yaml first\"\n        accept:\n          - cmd: cat\n            args: [\"deployment.yaml\"]\n            label: cat deployment.yaml\n        hint: cat deployment.yaml\n      - id: ex2\n        prompt: \"Apply it: kubectl apply -f deployment.yaml\"\n        accept:\n          - cmd: kubectl\n            args: [\"apply\", \"*\"]\n            canonical: \"kubectl apply -f deployment.yaml\"\n            flags: [[\"-f\", \"--filename\"]]\n            label: kubectl apply -f deployment.yaml\n        tips:\n          \"cmd:kubectl sub:apply noflag:-f\": \"kubectl apply needs the file flag: kubectl apply -f deployment.yaml\"\n        hint: kubectl apply -f deployment.yaml\n      - id: ex3\n        prompt: \"The deployment spawned pods — see them: kubectl get pods\"\n        accept:\n          - cmd: kubectl\n            args: [\"get\", \"pods\"]\n            label: kubectl get pods\n        hint: kubectl get pods\n    badge: declarer\n\n  - id: t3-l7\n    title: kubectl logs & describe — debug pods\n    tool: kubectl\n    world: k8s\n    intro: |\n      When a pod misbehaves:\n\n        kubectl logs <pod>          its output\n        kubectl describe pod <pod>  events, images, restarts — everything\n\n      One pod here is stuck in CrashLoopBackOff. Classic.\n    seed:\n      - op: k8sPod\n        name: web-app-7d9f8\n        image: web-app:latest\n      - op: k8sPod\n        name: worker-9s2k1\n        image: worker:2.1\n        kstatus: CrashLoopBackOff\n        restarts: 14\n        ready: \"0/1\"\n    exercises:\n      - id: ex1\n        prompt: \"Find the unhappy pod (look at STATUS)\"\n        accept:\n          - cmd: kubectl\n            args: [\"get\", \"pods\"]\n            label: kubectl get pods\n        hint: kubectl get pods\n      - id: ex2\n        prompt: \"Interrogate it: kubectl describe pod worker-9s2k1\"\n        accept:\n          - cmd: kubectl\n            args: [\"describe\", \"pod\", \"worker-9s2k1\"]\n            label: kubectl describe pod worker-9s2k1\n        hint: kubectl describe pod worker-9s2k1\n      - id: ex3\n        prompt: \"Read its logs\"\n        accept:\n          - cmd: kubectl\n            args: [\"logs\", \"worker-9s2k1\"]\n            label: kubectl logs worker-9s2k1\n        hint: kubectl logs worker-9s2k1\n    badge: pod-doctor\n\n  - id: t3-l8\n    title: BOSS — Deploy to the cluster\n    tool: kubectl\n    world: k8s\n    boss: true\n    intro: |\n      FINAL BOSS of Track 3: a full deployment, start to finish.\n\n      1. read deployment.yaml\n      2. apply it\n      3. verify pods are Running\n      4. expose it with service.yaml\n      5. verify services\n    seed:\n      - op: write\n        name: service.yaml\n        content: \"apiVersion: v1\\nkind: Service\\nmetadata:\\n  name: web-app-svc\\nspec:\\n  ports:\\n    - port: 80\\n\"\n      - op: write\n        name: deployment.yaml\n        content: \"apiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: web-app\\nspec:\\n  replicas: 3\\n  template:\\n    spec:\\n      containers:\\n        - name: web\\n          image: web-app:latest\\n\"\n    exercises:\n      - id: ex1\n        prompt: \"Step 1 — read deployment.yaml\"\n        accept:\n          - cmd: cat\n            args: [\"deployment.yaml\"]\n            label: cat deployment.yaml\n        hint: cat deployment.yaml\n      - id: ex2\n        prompt: \"Step 2 — apply it\"\n        accept:\n          - cmd: kubectl\n            args: [\"apply\", \"*\"]\n            canonical: \"kubectl apply -f deployment.yaml\"\n            flags: [[\"-f\", \"--filename\"]]\n            label: kubectl apply -f deployment.yaml\n        hint: kubectl apply -f deployment.yaml\n      - id: ex3\n        prompt: \"Step 3 — verify the pods\"\n        accept:\n          - cmd: kubectl\n            args: [\"get\", \"pods\"]\n            label: kubectl get pods\n        hint: kubectl get pods\n      - id: ex4\n        prompt: \"Step 4 — apply service.yaml\"\n        accept:\n          - cmd: kubectl\n            args: [\"apply\", \"*\"]\n            canonical: \"kubectl apply -f service.yaml\"\n            flags: [[\"-f\", \"--filename\"]]\n            label: kubectl apply -f service.yaml\n        hint: kubectl apply -f service.yaml\n      - id: ex5\n        prompt: \"Step 5 — verify the service\"\n        accept:\n          - cmd: kubectl\n            args: [\"get\", \"svc\"]\n            label: kubectl get svc\n          - cmd: kubectl\n            args: [\"get\", \"services\"]\n            label: kubectl get services\n        hint: kubectl get svc\n    badge: k8s-captain\n\n  - id: t3-l9\n    title: ffmpeg — transcode anything\n    tool: ffmpeg\n    world: ffmpeg\n    intro: |\n      ffmpeg converts, trims, and compresses audio/video. The pattern:\n\n        ffmpeg -i INPUT OUTPUT\n\n      -i marks the input; the output's extension sets the format.\n      video.mp4 is sitting there. Make it a .webm.\n    exercises:\n      - id: ex1\n        prompt: \"Convert video.mp4 to webm: ffmpeg -i video.mp4 video.webm\"\n        accept:\n          - cmd: ffmpeg\n            args: [\"video.mp4\", \"video.webm\"]\n            label: ffmpeg -i video.mp4 video.webm\n        tips:\n          \"cmd:ffmpeg sub:convert\": \"ffmpeg has no convert subcommand — the magic is in the flags: ffmpeg -i in.mp4 out.webm\"\n        hint: ffmpeg -i video.mp4 video.webm\n      - id: ex2\n        prompt: \"Check it worked — list files and look for video.webm\"\n        accept:\n          - cmd: ls\n            label: ls\n        hint: ls\n    badge: transcoder\n\n  - id: t3-l10\n    title: ffmpeg — extract audio\n    tool: ffmpeg\n    world: ffmpeg\n    intro: |\n      The -vn flag means \"no video\" — audio only:\n\n        ffmpeg -i video.mp4 -vn soundtrack.mp3\n\n      Extracting audio is one of ffmpeg's most-used tricks.\n    seed:\n      - op: write\n        name: movie.mp4\n        content: \"VIDEO 3840x2160 7200s AUDIO 48000Hz\"\n    exercises:\n      - id: ex1\n        prompt: \"Pull the audio out of movie.mp4 into soundtrack.mp3\"\n        accept:\n          - cmd: ffmpeg\n            args: [\"movie.mp4\", \"soundtrack.mp3\"]\n            label: ffmpeg -i movie.mp4 -vn soundtrack.mp3\n        tips:\n          \"cmd:ffmpeg\": \"put -vn between input and output: ffmpeg -i movie.mp4 -vn soundtrack.mp3\"\n        hint: ffmpeg -i movie.mp4 -vn soundtrack.mp3\n    badge: audio-extractor\n\n  - id: t3-l11\n    title: ffmpeg — trim the clip\n    tool: ffmpeg\n    world: ffmpeg\n    intro: |\n      Cut a slice out of media:\n\n        ffmpeg -ss 00:00:10 -i in.mp4 -t 5 out.mp4\n\n      -ss = start time, -t = duration in seconds.\n      This grabs 5 seconds starting at the 10-second mark.\n    seed:\n      - op: write\n        name: stream.mp4\n        content: \"VIDEO 1920x1080 3600s\"\n    exercises:\n      - id: ex1\n        prompt: \"Cut 5 seconds from stream.mp4 starting at 10s into clip.mp4\"\n        accept:\n          - cmd: ffmpeg\n            args: [\"stream.mp4\", \"clip.mp4\"]\n            label: ffmpeg -ss 00:00:10 -i stream.mp4 -t 5 clip.mp4\n        hint: ffmpeg -ss 00:00:10 -i stream.mp4 -t 5 clip.mp4\n    badge: clipper\n\n  - id: t3-l12\n    title: BOSS — The media pipeline\n    tool: ffmpeg\n    world: ffmpeg\n    boss: true\n    intro: |\n      BOSS: a real media pipeline in three commands.\n\n      1. convert episode.mp4 to episode.webm (smaller for web)\n      2. extract its audio to episode.mp3\n      3. list files to confirm everything exists\n    seed:\n      - op: write\n        name: episode.mp4\n        content: \"VIDEO 1920x1080 1800s AUDIO 48000Hz\"\n    exercises:\n      - id: ex1\n        prompt: \"Step 1 — convert to webm\"\n        accept:\n          - cmd: ffmpeg\n            args: [\"episode.mp4\", \"episode.webm\"]\n            label: ffmpeg -i episode.mp4 episode.webm\n        hint: ffmpeg -i episode.mp4 episode.webm\n      - id: ex2\n        prompt: \"Step 2 — extract the audio\"\n        accept:\n          - cmd: ffmpeg\n            args: [\"episode.mp4\", \"episode.mp3\"]\n            label: ffmpeg -i episode.mp4 -vn episode.mp3\n        hint: ffmpeg -i episode.mp4 -vn episode.mp3\n      - id: ex3\n        prompt: \"Step 3 — confirm your outputs\"\n        accept:\n          - cmd: ls\n            label: ls\n        hint: ls\n    badge: media-wizard\n"

